// Agent-readiness content negotiation for NapMovies.
//
// Serves the build-time Markdown mirrors in dist/ (generated by
// scripts/generate-seo-assets.mjs from the same route data and movie
// catalog as the HTML pages) when a client asks for
// Accept: text/markdown, and advertises those mirrors with a
// Link: rel="alternate"; type="text/markdown" header (plus Vary: Accept)
// on HTML responses. All other paths pass straight through to the
// static assets. Pattern follows Root Cause Casebook / SolveStack.

const markdownRoutes = new Set([
  "/",
  "/criteria/",
  "/movies-to-fall-asleep-to/",
  "/quiet-movies-for-bedtime/",
  "/comfort-movies-for-sleep/",
  "/visually-dark-movies-to-fall-asleep-to/",
]);

function appendVary(headers, value) {
  const values = new Set(
    (headers.get("Vary") || "")
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean),
  );
  values.add(value);
  headers.set("Vary", [...values].join(", "));
}

function withDiscoveryHeaders(response, canonicalUrl) {
  const headers = new Headers(response.headers);
  appendVary(headers, "Accept");
  headers.set(
    "Link",
    `<${canonicalUrl}>; rel="alternate"; type="text/markdown"`,
  );
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    // Normalise a bare slug ("/criteria") to its canonical route
    // ("/criteria/") so both spellings negotiate the same mirror.
    const route = markdownRoutes.has(url.pathname)
      ? url.pathname
      : markdownRoutes.has(`${url.pathname}/`)
        ? `${url.pathname}/`
        : null;
    if (!route) return env.ASSETS.fetch(request);

    const canonicalUrl = new URL(route, url.origin).toString();
    const wantsMarkdown = (request.headers.get("Accept") || "")
      .toLowerCase()
      .includes("text/markdown");

    if (wantsMarkdown) {
      const markdownPath =
        route === "/" ? "/index.md" : `${route.replace(/\/$/, "")}.md`;
      const markdownResponse = await env.ASSETS.fetch(
        new Request(new URL(markdownPath, url.origin), request),
      );
      if (markdownResponse.status === 200) {
        const headers = new Headers(markdownResponse.headers);
        headers.set("Content-Type", "text/markdown; charset=utf-8");
        appendVary(headers, "Accept");
        headers.set(
          "Link",
          `<${canonicalUrl}>; rel="canonical", <${canonicalUrl}>; rel="alternate"; type="text/markdown"`,
        );
        return new Response(markdownResponse.body, { status: 200, headers });
      }
    }

    const htmlResponse = await env.ASSETS.fetch(request);
    if (htmlResponse.status !== 200) return htmlResponse;
    return withDiscoveryHeaders(htmlResponse, canonicalUrl);
  },
};
